function openAiCompatibleBaseUrls(provider: KeatingCustomProvider): string[] {
	const baseUrl = trimTrailingSlash(provider.baseUrl);
	if (baseUrl.endsWith("/v1")) return [baseUrl];

	if (provider.type === "gateway" && provider.gatewayKind === "bifrost") {
		return [`${baseUrl}/v1`, `${baseUrl}/openai/v1`, baseUrl];
	}

	if (provider.type === "gateway") {
		return [`${baseUrl}/v1`, baseUrl];
	}

	return [baseUrl, `${baseUrl}/v1`];
}

async function fetchJson(url: string, apiKey?: string, options: { method?: "GET" | "POST"; body?: unknown } = {}): Promise<any> {
	const proxied = proxiedProviderRequestUrl(url);
	const headers: Record<string, string> = {
		"x-target-url": proxied.targetBaseUrl,
	};

	if (options.body !== undefined) headers["Content-Type"] = "application/json";
	if (apiKey) {
		headers.Authorization = `Bearer ${apiKey}`;
	}

	const response = await withApiRetry(async () => {
		const result = await fetch(proxied.url, {
			method: options.method ?? "GET",
			headers,
			body: options.body === undefined ? undefined : JSON.stringify(options.body),
		});
		if (!result.ok) {
			const retryAfter = result.headers.get("retry-after");
			throw new Error(`HTTP ${result.status}: ${result.statusText}${retryAfter ? ` retry-after: ${retryAfter}` : ""}`);
		}
		return result;
	});

	const text = await response.text();
	try {
		return JSON.parse(text);
	} catch {
		const snippet = text.trim().slice(0, 120).replace(/\s+/g, " ");
		throw new Error(
			`Expected JSON from ${url} but got ${snippet ? `a non-JSON response ("${snippet}…")` : "an empty response"}. Check the base URL.`,
		);
	}
}

async function discoverOpenAiCompatibleModels(
	provider: KeatingCustomProvider,
): Promise<{ apiBaseUrl: string; models: Model<Api>[] }> {
	const candidateBaseUrls = openAiCompatibleBaseUrls(provider);

	let lastError: unknown;
	let emptyResult: { apiBaseUrl: string; models: Model<Api>[] } | undefined;
	for (const apiBaseUrl of candidateBaseUrls) {
		try {
			const payload = await fetchJson(`${apiBaseUrl}/models`, provider.apiKey);
			const records = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload) ? payload : [];
				const models = records
					.map((record: any): Model<Api> | null => {
					const id = String(record?.id ?? record?.name ?? "").trim();
					if (!id) return null;

					const contextWindow = toContextWindow(
						record?.context_window ?? record?.context_length ?? record?.max_context_length ?? record?.max_model_len,
					);
					const maxTokens = toContextWindow(record?.max_tokens ?? record?.max_output_tokens, contextWindow || 4096);

					return {
						id,
						name: String(record?.display_name ?? record?.name ?? id),
						api: manualProviderApi(provider.type),
						provider: provider.name,
						baseUrl: apiBaseUrl,
						reasoning: inferReasoning(record),
						input: inferInputModes(record),
						cost: modelCost(),
						contextWindow,
						maxTokens,
					};
					})
					.filter((model: Model<Api> | null): model is Model<Api> => model !== null);

			if (models.length > 0) return { apiBaseUrl, models };
			emptyResult ??= { apiBaseUrl, models };
		} catch (error) {
			lastError = error;
		}
	}

	if (emptyResult) return emptyResult;
	throw lastError instanceof Error ? lastError : new Error(`Failed to discover models for ${provider.name}`);
}

async function discoverOllamaModels(baseUrl: string): Promise<Model<Api>[]> {
	const trimmedBaseUrl = trimTrailingSlash(baseUrl);
	const payload = await fetchJson(`${trimmedBaseUrl}/api/tags`);
	const models = Array.isArray(payload?.models) ? payload.models : [];

	const discovered = await Promise.all(
		models.map(async (model: any): Promise<Model<Api> | null> => {
			const details = await fetchJson(`${trimmedBaseUrl}/api/show`, undefined, {
				method: "POST",
				body: { model: model.name },
			});
			const capabilities: string[] = (details as any).capabilities || [];
			if (!capabilities.includes("tools")) return null;

			const modelInfo: any = details.model_info || {};
			const architecture = modelInfo["general.architecture"] || "";
			const contextWindow = toContextWindow(modelInfo[`${architecture}.context_length`], 8192);

			return {
				id: model.name,
				name: model.name,
				api: "openai-completions" as Api,
				provider: "",
				baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
				reasoning: capabilities.includes("thinking"),
				input: ["text"],
				cost: modelCost(),
				contextWindow,
				maxTokens: contextWindow,
			};
		}),
	);

	return discovered.filter((model): model is Model<Api> => model !== null);
}

